class Solution {
public:
    int appendCharacters(std::string s, std::string t) {
        size_t j = 0;
        for (char c : s) {
            if (j < t.size() && c == t[j]) j++;
        }
        return t.size() - j;
    }
};

class Solution {
    public int appendCharacters(String s, String t) {
        int j = 0;
        int lenT = t.length();
        for (int i = 0; i < s.length(); i++) {
            if (j < lenT && s.charAt(i) == t.charAt(j)) j++;
        }
        return lenT - j;
    }
}

var appendCharacters = function(s, t) {
    let j = 0;
    const lenT = t.length;
    for (let i = 0; i < s.length; i++) {
        if (j < lenT && s[i] === t[j]) j++;
    }
    return lenT - j;
};
